-- MEMBER SIGNUP: single initial installation transaction. Manual execution only.
-- Registration uses document versions and snapshots; no effective-date columns.
-- Signup availability reflects the explicit registrationEnabled configuration.
-- Source drafts below are inputs, not additional installation steps.
-- First inspect 20261022_member_signup_preflight.sql results. This candidate requires
-- profiles/languages/registration objects to be ABSENT and existing board aliases to match.
-- No account, member profile, post, comment, event, or admin record is deleted.
-- Existing schemas are never recreated. Any collision aborts the entire transaction.
-- Source: supabase/drafts/20261016_member_profiles_review.sql sha256=620054419a3010a193b5604a9dd78405ed45277f7e8c1f8ba42558741bcb1768
-- Source: supabase/drafts/20261020_member_nickname_consent_review.sql sha256=a65c5643638ffb6d1d1777cc414f65cb35eb134fb9c5cbd3619eacadc697af33
-- Source: supabase/drafts/20261023_member_signup_auth_profile.sql sha256=e33c722cbc539fcefce2e87498f28c24fbd290e2f3e87ecf225b33d513aa13c3
begin;
set local lock_timeout='3s';
set local statement_timeout='30s';
do $setup_preflight$
begin
 if not exists(select 1 from pg_roles where rolname=current_user and (rolsuper or rolbypassrls)) then raise exception 'Reviewed BYPASSRLS owner required';end if;
 if to_regclass('public.board_aliases') is null or to_regclass('auth.users') is null then raise exception 'Existing Auth/board prerequisites missing';end if;
 if exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('member_profiles','member_languages','member_registration_policies','member_policy_acceptances','member_signup_requests')) then raise exception 'Existing signup tables: prepare a metadata-specific additive change instead';end if;
 if exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'member_registration%' or p.proname like 'save_member_%' or p.proname like 'member_nickname_%' or p.proname in ('member_profile_protect','member_language_count_check'))) then raise exception 'Existing signup functions: stop, do not overwrite';end if;
end $setup_preflight$;
-- REVIEW DRAFT ONLY. Never run against production without DB-owner review.
-- Check remote objects/history first. No IF NOT EXISTS: collisions must fail.
-- If any prior draft/schema exists, review a separate data-preserving migration.
-- Never truncate existing languages or default an unanswered English level to none.
-- Apply as a migration owner with BYPASSRLS (normally postgres in Supabase).

create table public.member_profiles (
  user_id uuid primary key references auth.users(id) on delete cascade,
  name text check (name is null or (length(btrim(name)) between 1 and 100 and name !~ '[[:cntrl:]]')),
  phone_country_code text check (phone_country_code ~ '^[1-9][0-9]{0,2}$'),
  phone_number text check (phone_number ~ '^[0-9]{4,14}$'),
  nationality_code text check (nationality_code in ('AD','AE','AF','AG','AI','AL','AM','AO','AQ','AR','AS','AT','AU','AW','AX','AZ','BA','BB','BD','BE','BF','BG','BH','BI','BJ','BL','BM','BN','BO','BQ','BR','BS','BT','BV','BW','BY','BZ','CA','CC','CD','CF','CG','CH','CI','CK','CL','CM','CN','CO','CR','CU','CV','CW','CX','CY','CZ','DE','DJ','DK','DM','DO','DZ','EC','EE','EG','EH','ER','ES','ET','FI','FJ','FK','FM','FO','FR','GA','GB','GD','GE','GF','GG','GH','GI','GL','GM','GN','GP','GQ','GR','GS','GT','GU','GW','GY','HK','HM','HN','HR','HT','HU','ID','IE','IL','IM','IN','IO','IQ','IR','IS','IT','JE','JM','JO','JP','KE','KG','KH','KI','KM','KN','KP','KR','KW','KY','KZ','LA','LB','LC','LI','LK','LR','LS','LT','LU','LV','LY','MA','MC','MD','ME','MF','MG','MH','MK','ML','MM','MN','MO','MP','MQ','MR','MS','MT','MU','MV','MW','MX','MY','MZ','NA','NC','NE','NF','NG','NI','NL','NO','NP','NR','NU','NZ','OM','PA','PE','PF','PG','PH','PK','PL','PM','PN','PR','PS','PT','PW','PY','QA','RE','RO','RS','RU','RW','SA','SB','SC','SD','SE','SG','SH','SI','SJ','SK','SL','SM','SN','SO','SR','SS','ST','SV','SX','SY','SZ','TC','TD','TF','TG','TH','TJ','TK','TL','TM','TN','TO','TR','TT','TV','TW','TZ','UA','UG','UM','US','UY','UZ','VA','VC','VE','VG','VI','VN','VU','WF','WS','YE','YT','ZA','ZM','ZW')),
  gender text check (gender in ('female','male','undisclosed')),
  birth_date date not null check (birth_date >= date '0001-01-01'),
  korean_proficiency text not null check (korean_proficiency in ('none','basic','conversational','fluent','native')),
  english_proficiency text not null check (english_proficiency in ('none','basic','conversational','fluent','native')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint member_phone_pair check (
    (phone_country_code is null and phone_number is null) or
    (phone_country_code is not null and phone_number is not null and
     length(phone_country_code || phone_number) between 7 and 15)
  )
);
create table public.member_languages (
  user_id uuid not null references public.member_profiles(user_id) on delete cascade,
  language_code text not null check (language_code in ('ja','zh','es','fr','de','it','pt','ru','ar','vi','th','id','ms','tl','hi','bn','ur','ne','mn','uz','tr','uk','pl','nl','sv','fi','da','no','el','he','fa','sw','my','km','lo')),
  proficiency text not null check (proficiency in ('basic','conversational','fluent','native')),
  primary key (user_id, language_code)
);
comment on column public.member_profiles.phone_number is
  'Digits only, no country code. No verification claim. KR input drops one leading trunk zero.';
comment on table public.member_languages is
  'Curated 35 ISO 639-1 additional languages excluding ko and en. Expand UI/server/DB together after review.';

alter table public.member_profiles enable row level security;
alter table public.member_profiles force row level security;
alter table public.member_languages enable row level security;
alter table public.member_languages force row level security;
revoke all on public.member_profiles, public.member_languages from public, anon, authenticated;
grant select on public.member_profiles, public.member_languages to authenticated;
create policy "Members read own profile" on public.member_profiles
  for select to authenticated using ((select auth.uid()) = user_id);
create policy "Members read own languages" on public.member_languages
  for select to authenticated using ((select auth.uid()) = user_id);
-- INSERT/UPDATE/DELETE are deliberately not granted and have no direct-write policy.
-- All writes go through the narrow RPC below; callers cannot choose an owner UUID
-- or change created_at/updated_at. No admin_users exception in either SELECT policy.

create function public.member_profile_protect() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if tg_op = 'UPDATE' and (new.user_id is distinct from old.user_id or
                          new.created_at is distinct from old.created_at) then
    raise exception 'Protected member columns cannot change' using errcode = '23514';
  end if;
  if new.birth_date > ((current_timestamp at time zone 'Asia/Seoul')::date-interval '19 years')::date then
    raise exception 'Member must be at least 19' using errcode = '23514';
  end if;
  if tg_op = 'INSERT' then new.created_at := transaction_timestamp(); end if;
  new.updated_at := transaction_timestamp();
  return new;
end;
$$;
revoke all on function public.member_profile_protect() from public, anon, authenticated;
create trigger member_profile_protect before insert or update on public.member_profiles
  for each row execute function public.member_profile_protect();

-- Deferred checks permit atomic replacement of all language rows, but no committed
-- profile may have more than three additional languages. RPC locks the profile before replacement.
create function public.member_language_count_check() returns trigger
language plpgsql security definer set search_path = '' as $$
declare
  target uuid;
  total integer;
begin
  target := case when tg_op = 'DELETE' then old.user_id else new.user_id end;
  if exists(select 1 from public.member_profiles where user_id = target) then
    perform 1 from public.member_profiles where user_id = target for update;
    select count(*) into total from public.member_languages where user_id = target;
    if total not between 0 and 3 then
      raise exception 'Member may have 0 to 3 additional languages' using errcode = '23514';
    end if;
  end if;
  -- Additional-language ownership cannot be moved between members.
  if tg_op = 'UPDATE' and old.user_id is distinct from new.user_id and
     exists(select 1 from public.member_profiles where user_id = old.user_id) then
    raise exception 'Language ownership cannot change' using errcode = '23514';
  end if;
  return null;
end;
$$;
revoke all on function public.member_language_count_check() from public, anon, authenticated;
create constraint trigger member_profile_language_count
  after insert or update on public.member_profiles
  deferrable initially deferred for each row execute function public.member_language_count_check();
create constraint trigger member_language_count
  after insert or update or delete on public.member_languages
  deferrable initially deferred for each row execute function public.member_language_count_check();

-- No policy text/version is fabricated. DB owner must add approved, immutable
-- consent recording and required-field rules BEFORE replacing this null response.
create function public.member_registration_ready() returns text
language sql stable security invoker set search_path = '' as $$ select null::text $$;
revoke all on function public.member_registration_ready() from public, anon, authenticated;
grant execute on function public.member_registration_ready() to anon, authenticated;

create function public.save_member_profile(p_profile jsonb, p_languages jsonb, p_consent_version text)
returns uuid language plpgsql security definer set search_path = '' as $$
declare
  caller uuid := auth.uid();
  approved_version text := public.member_registration_ready();
begin
  if caller is null then raise exception 'Authentication required' using errcode = '42501'; end if;
  if approved_version is null or p_consent_version is distinct from approved_version then
    raise exception 'Registration policy is not ready' using errcode = '42501';
  end if;
  if jsonb_typeof(p_profile) is distinct from 'object' or
     jsonb_typeof(p_languages) is distinct from 'array' then
    raise exception 'Invalid profile payload' using errcode = '22023';
  end if;
  if jsonb_array_length(p_languages) not between 0 and 3 then
    raise exception 'Expected 0 to 3 additional languages' using errcode = '23514';
  end if;
  if exists (select 1 from jsonb_object_keys(p_profile) k
             where k not in ('name','phone_country_code','phone_number','nationality_code',
                             'gender','birth_date','korean_proficiency','english_proficiency')) then
    raise exception 'Unexpected profile field' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_array_elements(p_languages) entry
             where jsonb_typeof(entry) is distinct from 'object'
                or jsonb_typeof(entry->'language_code') is distinct from 'string'
                or jsonb_typeof(entry->'proficiency') is distinct from 'string') then
    raise exception 'Invalid language entry' using errcode = '22023';
  end if;
  -- Serializes first creation and later saves for this Auth UUID. Collisions only
  -- add contention; they cannot grant access. Existing profile also gets row lock.
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(caller::text, 0));
  insert into public.member_profiles (
    user_id,name,phone_country_code,phone_number,nationality_code,gender,birth_date,korean_proficiency,english_proficiency
  ) values (
    caller,p_profile->>'name',p_profile->>'phone_country_code',p_profile->>'phone_number',
    p_profile->>'nationality_code',p_profile->>'gender',(p_profile->>'birth_date')::date,
    p_profile->>'korean_proficiency',p_profile->>'english_proficiency'
  )
  on conflict (user_id) do update set
    name=excluded.name,phone_country_code=excluded.phone_country_code,phone_number=excluded.phone_number,
    nationality_code=excluded.nationality_code,gender=excluded.gender,birth_date=excluded.birth_date,
    korean_proficiency=excluded.korean_proficiency,english_proficiency=excluded.english_proficiency;
  perform 1 from public.member_profiles where user_id = caller for update;
  delete from public.member_languages where user_id = caller;
  insert into public.member_languages(user_id,language_code,proficiency)
    select caller,entry->>'language_code',entry->>'proficiency'
    from jsonb_array_elements(p_languages) entry;
  -- Version/time come from server policy/database clock. Never accept a client timestamp.
  return caller;
end;
$$;
revoke all on function public.save_member_profile(jsonb,jsonb,text) from public, anon, authenticated;
grant execute on function public.save_member_profile(jsonb,jsonb,text) to authenticated;

-- MANUAL REVIEW CANDIDATE. Never auto-run in a live Supabase project.
-- Additive extension ONLY after inspecting the installed profile/board metadata.
-- Does not create accounts, activate registration, change board RPC/RLS, rename
-- existing authors, delete rows, or implement account withdrawal.

do $preflight$
begin
 if current_setting('server_encoding')<>'UTF8' then raise exception 'UTF8 required';end if;
 if not exists(select 1 from pg_roles where rolname=current_user and (rolsuper or rolbypassrls)) then raise exception 'Reviewed BYPASSRLS migration owner required';end if;
 if to_regclass('public.member_profiles') is null or to_regclass('public.board_aliases') is null or
    to_regprocedure('public.save_member_profile(jsonb,jsonb,text)') is null or
    to_regprocedure('public.member_registration_ready()') is null then raise exception 'Review/apply profile prerequisites separately; do not rerun old drafts';end if;
 if to_regclass('public.member_registration_policies') is not null or to_regclass('public.member_policy_acceptances') is not null or
    to_regprocedure('public.save_member_registration_v2(text,jsonb,jsonb,text,text,text,boolean,boolean)') is not null then raise exception 'Objects already exist; inspect instead of recreating';end if;
 if exists(select 1 from pg_attribute where attrelid='public.board_aliases'::regclass and attname in ('nickname_key','nickname_chosen') and not attisdropped) then raise exception 'Alias extension already exists';end if;
 if exists(select 1 from public.board_aliases group by lower(normalize(nickname,NFKC)) having count(*)>1) then raise exception 'Existing normalized aliases collide. Resolve by reviewed, individual migration; never silently rename';end if;
 -- Existing direct profile writes must be closed; otherwise the new consent path
 -- could be bypassed. The legacy draft returns null until separate approval.
 if public.member_registration_ready() is not null then raise exception 'Legacy registration is active: review all callers and policy migration before applying';end if;
end $preflight$;

alter table public.board_aliases add column nickname_key text generated always as (lower(normalize(nickname,NFKC))) stored;
alter table public.board_aliases add column nickname_chosen boolean not null default false;
create unique index board_aliases_nickname_key_unique on public.board_aliases(nickname_key);

create table public.member_registration_policies(
 collection_version text primary key check(length(collection_version) between 1 and 100),
 terms_version text not null check(length(terms_version) between 1 and 100),
 privacy_version text not null check(length(privacy_version) between 1 and 100),
 collection_basis text not null check(collection_basis in ('consent','contract')),
 terms_snapshot jsonb not null check(jsonb_typeof(terms_snapshot)='object'),
 privacy_snapshot jsonb not null check(jsonb_typeof(privacy_snapshot)='object'),
 collection_snapshot jsonb not null check(jsonb_typeof(collection_snapshot)='object'),
 -- collection_version identifies the entire immutable acceptance bundle. A new
 -- document change after first acceptance requires a new bundle ID.
 check((terms_snapshot->>'version'=terms_version and privacy_snapshot->>'version'=privacy_version and collection_snapshot->>'version'=collection_version) is true),
 enabled boolean not null default false,created_at timestamptz not null default now()
);
create unique index member_registration_one_enabled on public.member_registration_policies(enabled) where enabled;
create table public.member_policy_acceptances(
 user_id uuid not null references auth.users(id), -- NO automatic deletion until retention/deletion review.
 collection_version text not null references public.member_registration_policies(collection_version),
 terms_accepted boolean not null check(terms_accepted),
 collection_accepted boolean not null,
 accepted_at timestamptz not null default clock_timestamp(),primary key(user_id,collection_version)
);
alter table public.member_registration_policies enable row level security;
alter table public.member_registration_policies force row level security;
alter table public.member_policy_acceptances enable row level security;
alter table public.member_policy_acceptances force row level security;
revoke all on public.member_registration_policies,public.member_policy_acceptances from public,anon,authenticated;

create function public.member_registration_policy_immutable() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if new.collection_version is distinct from old.collection_version then raise exception 'Policy bundle identity cannot change';end if;
 -- The row UPDATE lock serializes against the FOR SHARE lock in signup RPCs.
 -- Complete document metadata before first use; used snapshots are immutable.
 if exists(select 1 from public.member_policy_acceptances where collection_version=old.collection_version) and
    (to_jsonb(new)-'enabled') is distinct from (to_jsonb(old)-'enabled') then
  raise exception 'Accepted policy versions and snapshots are immutable. Insert a new bundle';
 end if;
 return new;
end $$;
revoke all on function public.member_registration_policy_immutable() from public,anon,authenticated;
create trigger member_registration_policy_immutable before update on public.member_registration_policies for each row execute function public.member_registration_policy_immutable();

-- Acceptance evidence is append-only. Reaccepting an existing bundle is a no-op.
create function public.member_policy_acceptance_immutable() returns trigger language plpgsql set search_path='' as $$
begin raise exception 'Acceptance evidence is immutable; insert a new policy bundle acceptance';end $$;
revoke all on function public.member_policy_acceptance_immutable() from public,anon,authenticated;
create trigger member_policy_acceptance_immutable before update on public.member_policy_acceptances for each row execute function public.member_policy_acceptance_immutable();

create function public.member_registration_v2_ready() returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object('terms_version',terms_version,'privacy_version',privacy_version,'collection_version',collection_version,'requires_consent',collection_basis='consent','enabled',enabled)
 from public.member_registration_policies where enabled and collection_version=public.member_registration_ready()
$$;
revoke all on function public.member_registration_v2_ready() from public,anon,authenticated;
grant execute on function public.member_registration_v2_ready() to anon,authenticated;

create function public.member_nickname_valid(p_nickname text) returns boolean language sql immutable set search_path='' as $$
 select coalesce(p_nickname ~ '^[A-Za-z0-9가-힣_]{2,20}$' and
  replace(lower(p_nickname),'_','') !~ '^(admin|administrator|moderator|system|staff|official|malmoim|formermember|관리자|운영자|운영진|시스템|공식|말모임|탈퇴한회원)',false)
$$;
revoke all on function public.member_nickname_valid(text) from public,anon,authenticated;
alter table public.board_aliases add constraint member_chosen_nickname_valid
 check(not nickname_chosen or public.member_nickname_valid(nickname));

create function public.member_nickname_available(p_nickname text) returns boolean language plpgsql stable security definer set search_path='' as $$
declare selected text:=btrim(normalize(p_nickname,NFKC));
begin
 if public.member_registration_v2_ready() is null then return null;end if;
 if not public.member_nickname_valid(selected) then return false;end if;
 return not exists(select 1 from public.board_aliases where nickname_key=lower(selected) and user_id is distinct from auth.uid());
end $$;
revoke all on function public.member_nickname_available(text) from public,anon,authenticated;
grant execute on function public.member_nickname_available(text) to anon,authenticated;

create function public.save_member_registration_v2(p_nickname text,p_profile jsonb,p_languages jsonb,p_consent_version text,p_terms_version text,p_privacy_version text,p_terms_accepted boolean,p_collection_accepted boolean)
returns uuid language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); policy public.member_registration_policies; selected text:=btrim(normalize(p_nickname,NFKC));birth date;existing public.board_aliases;result uuid;
begin
 if uid is null then raise exception 'Authentication required' using errcode='42501';end if;
 select * into policy from public.member_registration_policies where enabled and collection_version=p_consent_version for share;
 if not found or public.member_registration_v2_ready() is null or p_terms_version is distinct from policy.terms_version or p_privacy_version is distinct from policy.privacy_version or
    p_terms_accepted is distinct from true or (policy.collection_basis='consent' and p_collection_accepted is distinct from true) then raise exception 'Current policy acceptance required' using errcode='42501';end if;
 if not public.member_nickname_valid(selected) then raise exception 'Invalid nickname' using errcode='23514';end if;
 if jsonb_typeof(p_profile) is distinct from 'object' or coalesce(p_profile->>'birth_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Birth date required' using errcode='23514';end if;
 begin birth:=(p_profile->>'birth_date')::date;exception when others then raise exception 'Invalid birth date' using errcode='23514';end;
 if birth<date '0001-01-01' or birth>((now() at time zone 'Asia/Seoul')::date-interval '19 years')::date then raise exception 'Must be at least 19' using errcode='23514';end if;
 -- Use the legacy profile writer's advisory lock key to avoid lock inversions.
 perform pg_advisory_xact_lock(hashtextextended(uid::text,0));
 select * into existing from public.board_aliases where user_id=uid for update;
 if found and existing.nickname_chosen and existing.nickname is distinct from selected then raise exception 'Nickname changes are not supported' using errcode='42501';end if;
 if exists(select 1 from public.board_aliases where nickname_key=lower(selected) and user_id<>uid) then raise exception 'Nickname unavailable' using errcode='23505';end if;
 insert into public.board_aliases(user_id,nickname,nickname_chosen) values(uid,selected,true)
 on conflict(user_id) do update set nickname=excluded.nickname,nickname_chosen=true;
 -- Existing profile/language checks and trusted auth.uid() ownership are reused.
 -- Signup retries must not replace an existing profile or erase its optional
 -- fields/languages with the current required-only form. First creation remains
 -- atomic; a failed first save rolls back the alias and acceptance as well.
 if exists(select 1 from public.member_profiles where user_id=uid) then result:=uid;
 else result:=public.save_member_profile(p_profile,p_languages,p_consent_version);end if;
 if result is distinct from uid then raise exception 'Unverified profile result';end if;
 insert into public.member_policy_acceptances(user_id,collection_version,terms_accepted,collection_accepted)
 values(uid,policy.collection_version,true,case when policy.collection_basis='consent' then true else false end)
 on conflict(user_id,collection_version) do nothing;
 return uid;
end $$;
revoke all on function public.save_member_registration_v2(text,jsonb,jsonb,text,text,text,boolean,boolean) from public,anon,authenticated;
grant execute on function public.save_member_registration_v2(text,jsonb,jsonb,text,text,text,boolean,boolean) to authenticated;
-- Prevent direct bypass of nickname/age/acceptance checks when registration is
-- eventually approved. Confirm there are no other callers before manual apply.
revoke execute on function public.save_member_profile(jsonb,jsonb,text) from public,anon,authenticated;


-- Registration bundle: document versions, content snapshots and availability.
-- Technical availability only; no effective date or legal approval is inferred.
insert into public.member_registration_policies(collection_version,terms_version,privacy_version,collection_basis,terms_snapshot,privacy_snapshot,collection_snapshot,enabled)
values('signup-v1','terms-v1','privacy-v1','contract',
'{"version":"terms-v1","title":{"ko":"말모임(MALMOIM) 서비스 이용약관","en":"MALMOIM Terms of Service"},"introduction":{"ko":[],"en":[]},"sections":[{"id":"article-1","title":{"ko":"제1조 (목적)","en":"Article 1 (Purpose)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"본 약관은 말모임(MALMOIM, 이하 ''말모임'')이 제공하는 웹사이트, 언어교환 커뮤니티, 스터디 및 행사 관련 서비스의 이용 조건과 절차, 회원과 말모임의 권리·의무 및 책임사항을 정하는 것을 목적으로 합니다."}],"en":[{"type":"paragraph","text":"These Terms govern the conditions and procedures for using the website, language exchange community, studies, and event-related services provided by MALMOIM (hereinafter “MALMOIM”), as well as the rights, obligations, and responsibilities of members and MALMOIM."}]}},{"id":"article-2","title":{"ko":"제2조 (정의)","en":"Article 2 (Definitions)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"본 약관에서 사용하는 용어는 다음과 같습니다."},{"type":"list","ordered":true,"items":[{"text":"**말모임:** 운영진이 공동으로 운영하는 비영리 언어교환 커뮤니티","number":1},{"text":"**서비스:** 말모임 웹사이트, 회원 기능, 게시판, 스터디, 행사 신청 및 관련 프로그램","number":2},{"text":"**회원:** 본 약관에 동의하고 회원가입 절차를 완료한 이용자","number":3},{"text":"**비회원:** 회원가입 없이 공개된 서비스나 행사 정보를 이용하는 사람","number":4},{"text":"**운영진:** 말모임의 서비스 운영과 커뮤니티 관리 업무를 담당하는 사람","number":5},{"text":"**게시물:** 회원이 서비스에 등록하는 글, 댓글, 사진 및 기타 콘텐츠","number":6},{"text":"**행사:** 말모임이 주최하거나 운영하는 스터디, 언어교환 모임, 문화교류 프로그램 및 특별 행사","number":7}]}],"en":[{"type":"paragraph","text":"The following terms have the meanings set out below."},{"type":"list","ordered":true,"items":[{"text":"**MALMOIM:** A nonprofit language exchange community jointly operated by its organizers","number":1},{"text":"**Services:** The MALMOIM website, member functions, board, studies, event applications, and related programs","number":2},{"text":"**Member:** A user who agrees to these Terms and completes registration","number":3},{"text":"**Non-member:** A person who uses publicly available services or event information without registering","number":4},{"text":"**Organizers:** People responsible for operating MALMOIM’s services and managing its community","number":5},{"text":"**Content:** Posts, comments, photos, and other content that members submit to the services","number":6},{"text":"**Event:** A study, language exchange gathering, cultural exchange program, or special event hosted or operated by MALMOIM","number":7}]}]}},{"id":"article-3","title":{"ko":"제3조 (약관의 게시 및 변경)","en":"Article 3 (Publication and Amendment of the Terms)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임은 회원과 이용자가 본 약관을 쉽게 확인할 수 있도록 홈페이지에 게시합니다."},{"type":"paragraph","text":"② 말모임은 관련 법령을 위반하지 않는 범위에서 본 약관을 변경할 수 있습니다."},{"type":"paragraph","text":"③ 약관을 변경하는 경우 시행일과 변경 내용을 홈페이지를 통해 사전에 안내합니다. 회원에게 불리한 중요한 변경의 경우 관계 법령에 따라 필요한 고지 및 동의 절차를 진행합니다."},{"type":"paragraph","text":"④ 변경된 약관은 법령상 허용되는 범위에서 적용되며, 이용자의 법적 권리를 부당하게 제한하지 않습니다."}],"en":[{"type":"paragraph","text":"① MALMOIM publishes these Terms on its website so that members and users can easily review them."},{"type":"paragraph","text":"② MALMOIM may amend these Terms to the extent that doing so does not violate applicable law."},{"type":"paragraph","text":"③ When amending these Terms, MALMOIM announces the effective date and changes on its website in advance. For material changes unfavorable to members, MALMOIM follows the notice and consent procedures required by applicable law."},{"type":"paragraph","text":"④ Amended Terms apply to the extent permitted by law and do not unfairly restrict users’ legal rights."}]}},{"id":"article-4","title":{"ko":"제4조 (서비스의 내용)","en":"Article 4 (Services)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임은 한국어·영어를 중심으로 언어 및 문화교류 활동을 지원합니다."},{"type":"paragraph","text":"② 말모임은 다음 서비스를 제공할 수 있습니다."},{"type":"list","ordered":true,"items":[{"text":"회원가입 및 회원 계정 관리","number":1},{"text":"언어교환 커뮤니티 및 게시판","number":2},{"text":"스터디와 언어교환 프로그램","number":3},{"text":"오프라인 및 온라인 행사","number":4},{"text":"행사 신청 및 참가자 관리","number":5},{"text":"기타 말모임이 제공하는 관련 서비스","number":6}]},{"type":"paragraph","text":"③ 개별 스터디나 행사에는 참가비가 발생할 수 있으며, 참가비와 세부 조건은 각 행사 안내에서 확인할 수 있습니다."},{"type":"paragraph","text":"④ 서비스의 구체적인 구성과 제공 범위는 운영 상황에 따라 변경될 수 있습니다."}],"en":[{"type":"paragraph","text":"① MALMOIM supports language and cultural exchange activities, primarily in Korean and English."},{"type":"paragraph","text":"② MALMOIM may provide the following services."},{"type":"list","ordered":true,"items":[{"text":"Registration and member account management","number":1},{"text":"A language exchange community and board","number":2},{"text":"Studies and language exchange programs","number":3},{"text":"Offline and online events","number":4},{"text":"Event applications and participant management","number":5},{"text":"Other related services provided by MALMOIM","number":6}]},{"type":"paragraph","text":"③ Participation fees may apply to individual studies or events. Fees and detailed conditions are provided in each event’s information."},{"type":"paragraph","text":"④ The specific composition and scope of the services may change depending on operating circumstances."}]}},{"id":"article-5","title":{"ko":"제5조 (회원가입 및 가입 자격)","en":"Article 5 (Registration and Eligibility)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임의 회원가입 대상은 만 19세 이상인 사람입니다."},{"type":"paragraph","text":"② 회원가입을 희망하는 사람은 필수 정보를 입력하고 본 약관에 동의해야 합니다."},{"type":"paragraph","text":"③ 회원가입 시 필요한 필수 정보는 다음과 같습니다."},{"type":"list","ordered":true,"items":[{"text":"이메일 주소 및 비밀번호","number":1},{"text":"닉네임","number":2},{"text":"생년월일","number":3},{"text":"한국어 수준","number":4},{"text":"영어 수준","number":5}]},{"type":"paragraph","text":"④ 다음 정보는 선택적으로 제공할 수 있습니다."},{"type":"list","ordered":true,"items":[{"text":"이름","number":1},{"text":"전화번호 및 국가번호","number":2},{"text":"국적","number":3},{"text":"성별","number":4},{"text":"추가 외국어 및 언어 수준","number":5}]},{"type":"paragraph","text":"⑤ 선택 정보를 제공하지 않았다는 이유만으로 기본적인 회원가입 및 커뮤니티 이용을 제한하지 않습니다."},{"type":"paragraph","text":"⑥ 말모임은 다음 경우 회원가입을 제한하거나 관련 법령과 운영 정책에 따라 필요한 조치를 할 수 있습니다."},{"type":"list","ordered":true,"items":[{"text":"만 19세 미만인 경우","number":1},{"text":"타인의 정보를 무단 사용한 경우","number":2},{"text":"필수 정보를 허위로 기재한 경우","number":3},{"text":"서비스의 정상적인 운영을 방해할 목적이 명백한 경우","number":4},{"text":"관계 법령을 위반하는 경우","number":5}]},{"type":"paragraph","text":"⑦ 회원가입 처리 과정에서 개인정보는 별도의 개인정보 처리방침에 따라 처리합니다."}],"en":[{"type":"paragraph","text":"① Registration with MALMOIM is available to people aged 19 or older."},{"type":"paragraph","text":"② People wishing to register must provide the required information and agree to these Terms."},{"type":"paragraph","text":"③ The following information is required for registration."},{"type":"list","ordered":true,"items":[{"text":"Email address and password","number":1},{"text":"Nickname","number":2},{"text":"Date of birth","number":3},{"text":"Korean proficiency","number":4},{"text":"English proficiency","number":5}]},{"type":"paragraph","text":"④ The following information may be provided optionally."},{"type":"list","ordered":true,"items":[{"text":"Name","number":1},{"text":"Phone number and country calling code","number":2},{"text":"Nationality","number":3},{"text":"Gender","number":4},{"text":"Additional languages and proficiency","number":5}]},{"type":"paragraph","text":"⑤ Basic registration and community use are not restricted solely because optional information has not been provided."},{"type":"paragraph","text":"⑥ MALMOIM may restrict registration or take necessary measures under applicable law and operating policies in the following cases."},{"type":"list","ordered":true,"items":[{"text":"The person is under 19","number":1},{"text":"The person has used someone else’s information without authorization","number":2},{"text":"Required information has been provided falsely","number":3},{"text":"There is a clear purpose of disrupting normal service operation","number":4},{"text":"Applicable law is violated","number":5}]},{"type":"paragraph","text":"⑦ Personal information during registration is processed under the separate Privacy Policy."}]}},{"id":"article-6","title":{"ko":"제6조 (회원의 계정 관리)","en":"Article 6 (Member Account Management)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 회원은 자신의 계정정보를 안전하게 관리해야 합니다."},{"type":"paragraph","text":"② 회원은 타인의 계정을 무단으로 사용하거나 자신의 계정을 부정한 목적으로 제공해서는 안 됩니다."},{"type":"paragraph","text":"③ 회원은 계정이 무단으로 이용되었거나 보안상 문제가 발생한 사실을 알게 된 경우 말모임에 알릴 수 있습니다."},{"type":"paragraph","text":"④ 말모임은 서비스의 안전한 운영을 위해 필요한 인증 및 접근통제 조치를 실시할 수 있습니다."}],"en":[{"type":"paragraph","text":"① Members must manage their account information securely."},{"type":"paragraph","text":"② Members must not use another person’s account without authorization or provide their own account for an improper purpose."},{"type":"paragraph","text":"③ Members may notify MALMOIM if they become aware of unauthorized account use or a security issue."},{"type":"paragraph","text":"④ MALMOIM may implement authentication and access-control measures necessary for safe service operation."}]}},{"id":"article-7","title":{"ko":"제7조 (닉네임 및 회원정보)","en":"Article 7 (Nicknames and Member Information)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 회원은 회원가입 시 닉네임을 설정해야 합니다."},{"type":"paragraph","text":"② 닉네임은 게시판과 댓글에서 작성자 표시명으로 사용됩니다."},{"type":"paragraph","text":"③ 회원은 타인을 사칭하거나 다른 회원에게 혼동을 줄 수 있는 닉네임을 사용해서는 안 됩니다."},{"type":"paragraph","text":"④ 말모임은 욕설, 차별적 표현, 타인의 권리 침해 등 운영 정책에 위반되는 닉네임의 변경을 요청하거나 관련 조치를 취할 수 있습니다."},{"type":"paragraph","text":"⑤ 회원정보의 변경과 개인정보 처리에 관한 사항은 개인정보 처리방침 및 해당 서비스 기능에 따릅니다."}],"en":[{"type":"paragraph","text":"① Members must set a nickname when registering."},{"type":"paragraph","text":"② Nicknames are used as author display names on the board and in comments."},{"type":"paragraph","text":"③ Members must not use nicknames that impersonate others or may confuse other members."},{"type":"paragraph","text":"④ MALMOIM may request a change to a nickname that violates operating policies, including through profanity, discriminatory expressions, or infringement of others’ rights, or take related measures."},{"type":"paragraph","text":"⑤ Changes to member information and the processing of personal information are governed by the Privacy Policy and the relevant service functions."}]}},{"id":"article-8","title":{"ko":"제8조 (회원의 의무 및 금지행위)","en":"Article 8 (Members’ Obligations and Prohibited Conduct)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"회원은 서비스를 이용하면서 관계 법령과 본 약관, 공지된 커뮤니티 운영 정책을 준수해야 합니다."},{"type":"paragraph","text":"다음 행위는 금지됩니다."},{"type":"list","ordered":true,"items":[{"text":"다른 이용자에 대한 괴롭힘, 협박, 혐오·차별적 언행","number":1},{"text":"원하지 않는 반복적인 연락이나 스팸 게시","number":2},{"text":"타인의 개인정보를 동의나 적법한 근거 없이 수집·공개하는 행위","number":3},{"text":"타인의 명예, 초상권, 저작권 등 권리를 침해하는 행위","number":4},{"text":"허위정보를 이용한 사기나 금전 요구","number":5},{"text":"무단 광고 및 영리적 홍보","number":6},{"text":"계정 도용, 부정 접근 및 서비스 운영 방해","number":7},{"text":"불법 콘텐츠 게시 및 기타 관계 법령을 위반하는 행위","number":8}]},{"type":"paragraph","text":"말모임은 커뮤니티의 안전과 질서 유지를 위해 합리적인 범위에서 세부 운영 규칙을 마련할 수 있습니다."}],"en":[{"type":"paragraph","text":"Members must comply with applicable law, these Terms, and announced community operating policies when using the services."},{"type":"paragraph","text":"The following conduct is prohibited."},{"type":"list","ordered":true,"items":[{"text":"Harassment, threats, or hateful or discriminatory conduct toward other users","number":1},{"text":"Unwanted repeated contact or spam posts","number":2},{"text":"Collecting or disclosing others’ personal information without consent or another lawful basis","number":3},{"text":"Infringing others’ rights, including reputation, portrait rights, and copyright","number":4},{"text":"Fraud or demands for money using false information","number":5},{"text":"Unauthorized advertising and commercial promotion","number":6},{"text":"Account theft, unauthorized access, and disruption of service operation","number":7},{"text":"Posting illegal content and other conduct that violates applicable law","number":8}]},{"type":"paragraph","text":"MALMOIM may establish detailed operating rules within reasonable limits to maintain the community’s safety and order."}]}},{"id":"article-9","title":{"ko":"제9조 (게시물 및 저작권)","en":"Article 9 (Content and Copyright)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 회원이 직접 작성한 게시물의 저작권은 원칙적으로 해당 작성자에게 귀속됩니다."},{"type":"paragraph","text":"② 회원은 자신에게 적법한 이용 권한이 있는 콘텐츠만 게시해야 합니다."},{"type":"paragraph","text":"③ 회원은 게시물을 등록함으로써 말모임이 서비스 제공에 필요한 범위에서 해당 게시물을 저장, 표시, 전송 및 기술적으로 필요한 형태로 처리하는 것을 허용합니다."},{"type":"paragraph","text":"④ 말모임은 회원의 콘텐츠를 서비스 제공과 무관한 광고·홍보 등 별도의 목적으로 이용하려는 경우 필요한 권리와 법적 근거를 확보합니다."},{"type":"paragraph","text":"⑤ 회원은 자신이 작성한 게시물의 수정 또는 삭제를 요청할 수 있습니다. 구체적인 처리 절차는 서비스 기능과 관련 법령에 따릅니다."}],"en":[{"type":"paragraph","text":"① Copyright in content created directly by a member belongs, in principle, to that author."},{"type":"paragraph","text":"② Members must post only content that they have a lawful right to use."},{"type":"paragraph","text":"③ By submitting content, members permit MALMOIM to store, display, transmit, and process it in technically necessary forms to the extent necessary to provide the services."},{"type":"paragraph","text":"④ If MALMOIM intends to use a member’s content for a separate purpose unrelated to service provision, such as advertising or promotion, it secures the necessary rights and legal basis."},{"type":"paragraph","text":"⑤ Members may request modification or deletion of their own content. The specific procedures follow the service functions and applicable law."}]}},{"id":"article-10","title":{"ko":"제10조 (게시물 관리 및 이용 제한)","en":"Article 10 (Content Management and Restrictions on Use)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임은 게시물이 관련 법령 또는 커뮤니티 운영 정책을 위반한 경우 필요한 조치를 할 수 있습니다."},{"type":"paragraph","text":"② 조치에는 게시물의 비공개 또는 삭제, 수정 요청, 기능 이용 제한, 계정 이용 제한 등이 포함될 수 있습니다."},{"type":"paragraph","text":"③ 말모임은 위반 행위의 성격, 정도, 반복 여부 및 다른 이용자에게 미치는 영향을 고려하여 합리적으로 조치합니다."},{"type":"paragraph","text":"④ 필요한 경우 조치 사유와 이의제기 방법을 해당 회원에게 안내합니다. 다만 법령 준수, 긴급한 피해 방지 또는 다른 이용자의 권리 보호 등을 위해 사전 안내가 어려울 수 있습니다."},{"type":"paragraph","text":"⑤ 회원은 말모임의 조치에 이의가 있을 경우 공식 문의처로 재검토를 요청할 수 있습니다."}],"en":[{"type":"paragraph","text":"① MALMOIM may take necessary measures when content violates applicable law or community operating policies."},{"type":"paragraph","text":"② Measures may include making content private or deleting it, requesting modifications, restricting functions, and restricting account use."},{"type":"paragraph","text":"③ MALMOIM takes reasonable measures with regard to the nature, severity, repetition, and impact of the violation on other users."},{"type":"paragraph","text":"④ Where necessary, MALMOIM informs the member of the reasons and how to object. Advance notice may be difficult where required for compliance with law, urgent prevention of harm, or protection of other users’ rights."},{"type":"paragraph","text":"⑤ Members who object to a measure may request reconsideration through the official contact."}]}},{"id":"article-11","title":{"ko":"제11조 (회원 탈퇴 및 게시물의 처리)","en":"Article 11 (Membership Withdrawal and Content)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 회원은 말모임이 제공하는 절차 또는 공식 문의처를 통해 탈퇴를 요청할 수 있습니다."},{"type":"paragraph","text":"② 회원 탈퇴 시 계정 및 개인정보는 개인정보 처리방침과 관련 법령에 따라 처리합니다."},{"type":"paragraph","text":"③ 회원 탈퇴 이후에도 회원이 작성한 게시글과 댓글은 커뮤니티의 대화 맥락 유지를 위해 남을 수 있습니다."},{"type":"paragraph","text":"④ 탈퇴한 회원의 공개 작성자 표시는 ''탈퇴한 회원(Former Member)''으로 변경하고, 공개 프로필과의 연결을 해제하는 것을 원칙으로 합니다."},{"type":"paragraph","text":"⑤ 회원은 탈퇴하기 전에 자신의 게시물을 삭제할 수 있으며, 탈퇴 후에도 게시물에 포함된 개인정보에 관하여 관련 법령상 권리를 행사할 수 있습니다."},{"type":"paragraph","text":"⑥ 법령상 보존 의무가 있는 정보는 관련 법령에 따라 필요한 기간 동안 보존될 수 있습니다."}],"en":[{"type":"paragraph","text":"① Members may request withdrawal through the procedure provided by MALMOIM or its official contact."},{"type":"paragraph","text":"② Upon withdrawal, accounts and personal information are handled under the Privacy Policy and applicable law."},{"type":"paragraph","text":"③ Posts and comments written by members may remain after withdrawal to preserve the context of community conversations."},{"type":"paragraph","text":"④ The principle is to change the public author label of a withdrawn member to “탈퇴한 회원(Former Member)” and disconnect it from the public profile."},{"type":"paragraph","text":"⑤ Members may delete their content before withdrawal and may exercise rights under applicable law concerning personal information in their content after withdrawal as well."},{"type":"paragraph","text":"⑥ Information subject to a statutory preservation obligation may be retained for the necessary period under applicable law."}]}},{"id":"article-12","title":{"ko":"제12조 (스터디 및 행사 신청)","en":"Article 12 (Study and Event Applications)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임은 온라인 또는 오프라인에서 스터디, 언어교환 모임 및 특별 행사를 운영할 수 있습니다."},{"type":"paragraph","text":"② 행사에 따라 참가 자격, 인원 제한, 신청 기간, 장소 및 참가비 등이 다를 수 있습니다."},{"type":"paragraph","text":"③ 말모임은 이용자가 신청 전에 행사 내용, 일정, 장소, 참가비, 신청 절차 및 취소·환불 조건을 확인할 수 있도록 안내합니다."},{"type":"paragraph","text":"④ 참가 신청의 확정 시점과 절차는 각 행사 안내에 따릅니다."},{"type":"paragraph","text":"⑤ 참가자는 행사별 안내사항과 안전수칙을 준수하고 다른 참가자의 권리를 존중해야 합니다."},{"type":"paragraph","text":"⑥ 말모임은 행사 운영에 필요한 범위에서 신청 및 참가정보를 처리하며, 구체적인 내용은 개인정보 처리방침에 따릅니다."}],"en":[{"type":"paragraph","text":"① MALMOIM may operate studies, language exchange gatherings, and special events online or offline."},{"type":"paragraph","text":"② Eligibility, capacity, application periods, locations, and participation fees may differ by event."},{"type":"paragraph","text":"③ MALMOIM provides information so that users can check event details, schedules, locations, fees, application procedures, and cancellation and refund conditions before applying."},{"type":"paragraph","text":"④ The timing and procedure for confirming participation follow each event’s information."},{"type":"paragraph","text":"⑤ Participants must comply with event-specific information and safety rules and respect other participants’ rights."},{"type":"paragraph","text":"⑥ MALMOIM processes application and participation information to the extent necessary for event operation. Details follow the Privacy Policy."}]}},{"id":"article-13","title":{"ko":"제13조 (참가비 결제, 취소 및 환불)","en":"Article 13 (Payment of Participation Fees, Cancellation, and Refunds)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임의 유료 행사 참가비는 행사별 안내에 따라 사전 계좌이체 또는 현장 결제 방식으로 납부할 수 있습니다."},{"type":"paragraph","text":"② 말모임은 행사별로 참가비, 납부기한, 참가 확정 기준, 취소 방법, 전액 환불 가능 기한 및 기한 이후 환불 조건을 신청 전에 안내합니다."},{"type":"paragraph","text":"③ 말모임은 공통적인 환불 원칙을 적용하되, 장소 대관, 식음료 준비, 외부 업체 예약 및 프로그램 운영 등 행사별 특성에 따라 서로 다른 환불 기준을 정할 수 있습니다."},{"type":"paragraph","text":"④ 행사별 환불 기준은 신청 전에 명확히 고지하며, 사전에 안내되지 않은 불리한 조건을 사후에 일방적으로 적용하지 않습니다."},{"type":"paragraph","text":"⑤ 참가자는 안내된 절차에 따라 참가 취소 또는 환불을 요청할 수 있습니다. 관계 법령에서 청약철회·취소·환불 권리를 보장하는 경우 해당 법령을 우선 적용합니다."},{"type":"paragraph","text":"⑥ 말모임의 사정으로 행사가 취소되어 예정된 서비스가 제공되지 않는 경우 이미 납부한 참가비를 전액 환불합니다."},{"type":"paragraph","text":"⑦ 행사 일정, 장소 또는 주요 내용이 실질적으로 변경되는 경우 말모임은 참가자에게 안내하며, 관련 법령 및 변경 사유에 따라 필요한 취소·환불 조치를 제공합니다."},{"type":"paragraph","text":"⑧ 환불에 필요한 계좌정보 등은 환불 목적 범위에서 처리하며, 개인정보 처리방침 및 관계 법령에 따라 보관·파기합니다."},{"type":"paragraph","text":"⑨ 행사별 환불 조건은 법령에서 보장하는 이용자의 권리를 부당하게 제한할 수 없습니다."}],"en":[{"type":"paragraph","text":"① Participation fees for MALMOIM’s paid events may be paid by advance bank transfer or on-site payment, as specified for each event."},{"type":"paragraph","text":"② Before applications, MALMOIM provides event-specific information on fees, payment deadlines, participation confirmation criteria, cancellation methods, deadlines for full refunds, and refund conditions after those deadlines."},{"type":"paragraph","text":"③ MALMOIM applies common refund principles but may establish different refund criteria according to each event’s characteristics, including venue rental, food and beverage preparation, external supplier reservations, and program operation."},{"type":"paragraph","text":"④ Event-specific refund criteria are clearly disclosed before applications. Unfavorable conditions not announced in advance are not imposed unilaterally afterward."},{"type":"paragraph","text":"⑤ Participants may request cancellation or a refund through the announced procedures. Where applicable law guarantees rights to withdraw, cancel, or receive a refund, that law takes precedence."},{"type":"paragraph","text":"⑥ If an event is canceled for reasons attributable to MALMOIM and the scheduled service is not provided, fees already paid are refunded in full."},{"type":"paragraph","text":"⑦ If the schedule, location, or main content of an event changes materially, MALMOIM notifies participants and provides necessary cancellation and refund measures according to applicable law and the reasons for the change."},{"type":"paragraph","text":"⑧ Account information and other information needed for refunds are processed only for the refund purpose and retained or destroyed under the Privacy Policy and applicable law."},{"type":"paragraph","text":"⑨ Event-specific refund conditions must not unfairly restrict users’ rights guaranteed by law."}]}},{"id":"article-14","title":{"ko":"제14조 (오프라인 활동 및 사진·영상)","en":"Article 14 (Offline Activities, Photos, and Videos)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 참가자는 행사장 이용 규칙, 안전수칙 및 운영진의 합리적인 안내를 준수해야 합니다."},{"type":"paragraph","text":"② 말모임은 다른 참가자에 대한 괴롭힘, 폭력, 성희롱 등 안전을 위협하는 행위가 발생한 경우 해당 참가자에게 행사 중단이나 퇴장을 요청할 수 있습니다."},{"type":"paragraph","text":"③ 행사 과정에서 사진과 영상이 촬영될 수 있으나, 참가비 결제 또는 본 약관 동의만으로 참가자의 초상이나 개인정보를 모든 홍보 목적으로 공개하는 데 동의한 것으로 보지 않습니다."},{"type":"paragraph","text":"④ 사진·영상의 촬영, 보관 및 외부 공개와 관련하여 별도의 법적 근거 또는 동의가 필요한 경우 말모임은 필요한 안내와 절차를 진행합니다."}],"en":[{"type":"paragraph","text":"① Participants must follow venue rules, safety rules, and reasonable instructions from organizers."},{"type":"paragraph","text":"② MALMOIM may ask a participant to stop participating or leave if the participant engages in conduct threatening safety, including harassment, violence, or sexual harassment toward other participants."},{"type":"paragraph","text":"③ Photos and videos may be taken during events. However, paying a participation fee or agreeing to these Terms alone is not deemed consent to publicly disclose a participant’s likeness or personal information for all promotional purposes."},{"type":"paragraph","text":"④ Where a separate legal basis or consent is necessary for taking, retaining, or externally disclosing photos and videos, MALMOIM provides the necessary information and procedures."}]}},{"id":"article-15","title":{"ko":"제15조 (서비스 변경 및 중단)","en":"Article 15 (Changes to and Suspension of Services)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임은 시스템 점검, 장애, 보안 문제 또는 불가피한 운영상 사유로 서비스의 일부 또는 전부를 변경하거나 일시 중단할 수 있습니다."},{"type":"paragraph","text":"② 사전에 예측할 수 있는 변경이나 중단은 가능한 범위에서 미리 안내합니다."},{"type":"paragraph","text":"③ 유료 행사 등 이미 체결된 계약에 영향을 주는 변경은 해당 계약과 관계 법령에 따라 처리합니다."}],"en":[{"type":"paragraph","text":"① MALMOIM may change or temporarily suspend some or all services due to system maintenance, failures, security issues, or unavoidable operational reasons."},{"type":"paragraph","text":"② Changes or suspensions that can be anticipated are announced in advance where possible."},{"type":"paragraph","text":"③ Changes affecting agreements already entered into, including paid events, are handled under those agreements and applicable law."}]}},{"id":"article-16","title":{"ko":"제16조 (개인정보 보호)","en":"Article 16 (Protection of Personal Information)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 회원 및 참가자의 개인정보를 관련 법령과 별도로 공개한 개인정보 처리방침에 따라 처리합니다."},{"type":"paragraph","text":"개인정보 처리방침은 홈페이지에서 확인할 수 있으며, 본 약관과 구별하여 공개합니다."}],"en":[{"type":"paragraph","text":"MALMOIM processes members’ and participants’ personal information under applicable law and its separately published Privacy Policy."},{"type":"paragraph","text":"The Privacy Policy is available on the website and is published separately from these Terms."}]}},{"id":"article-17","title":{"ko":"제17조 (책임 및 분쟁 해결)","en":"Article 17 (Liability and Dispute Resolution)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임과 회원은 관련 법령 및 본 약관에 따른 의무를 준수해야 합니다."},{"type":"paragraph","text":"② 말모임은 자신에게 귀책사유가 있는 서비스 운영상 문제에 대해 관련 법령에 따라 책임을 부담합니다."},{"type":"paragraph","text":"③ 다른 참가자의 불법행위나 회원 간 분쟁에 대해서도 말모임에 별도의 법적 책임이 발생하는 경우에는 그 책임이 배제되지 않습니다."},{"type":"paragraph","text":"④ 서비스 이용과 관련된 분쟁이 발생하는 경우 당사자는 우선 원만한 해결을 위해 협의할 수 있으며, 협의로 해결되지 않는 경우 관계 법령에 따른 절차를 이용할 수 있습니다."},{"type":"paragraph","text":"⑤ 본 약관의 해석 및 관련 분쟁에는 대한민국 법령을 적용하며, 소송이 필요한 경우 법령에 따른 관할법원에서 해결합니다."}],"en":[{"type":"paragraph","text":"① MALMOIM and members must comply with their obligations under applicable law and these Terms."},{"type":"paragraph","text":"② MALMOIM bears liability under applicable law for service operation issues attributable to it."},{"type":"paragraph","text":"③ Liability is not excluded where MALMOIM has a separate legal responsibility in connection with another participant’s unlawful acts or disputes between members."},{"type":"paragraph","text":"④ If a dispute arises in connection with service use, the parties may first consult to seek an amicable resolution. If consultation does not resolve it, they may use procedures under applicable law."},{"type":"paragraph","text":"⑤ The laws of the Republic of Korea govern the interpretation of these Terms and related disputes. Where litigation is necessary, disputes are resolved by the court with jurisdiction under law."}]}},{"id":"article-18","title":{"ko":"제18조 (문의처 및 약관 시행)","en":"Article 18 (Contact and Commencement of the Terms)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"서비스 이용, 행사 및 약관에 관한 문의는 다음 연락처로 접수할 수 있습니다."},{"type":"list","ordered":false,"items":[{"text":"운영 주체: 말모임(MALMOIM)"},{"text":"담당: 말모임 운영팀"},{"text":"이메일: cometomalmoim@gmail.com"},{"text":"홈페이지: https://malmoim.com"}]}],"en":[{"type":"paragraph","text":"Inquiries about service use, events, and these Terms may be submitted through the following contact details."},{"type":"list","ordered":false,"items":[{"text":"Operator: MALMOIM"},{"text":"Responsible team: MALMOIM Operations Team"},{"text":"Email: cometomalmoim@gmail.com"},{"text":"Website: https://malmoim.com"}]}]}}]}'::jsonb,
'{"version":"privacy-v1","title":{"ko":"말모임(MALMOIM) 개인정보 처리방침","en":"MALMOIM Privacy Policy"},"introduction":{"ko":[{"type":"paragraph","text":"말모임(MALMOIM, 이하 ''말모임'')은 운영진이 공동으로 운영하는 비영리 언어교환 커뮤니티입니다. 말모임은 이용자의 개인정보를 보호하고 관련 고충을 처리하기 위해 「개인정보 보호법」 등 관계 법령을 준수하며, 다음과 같이 개인정보 처리방침을 수립합니다."}],"en":[{"type":"paragraph","text":"MALMOIM (hereinafter “MALMOIM”) is a nonprofit language exchange community jointly operated by its organizers. To protect users’ personal information and address related complaints, MALMOIM complies with applicable laws, including the Personal Information Protection Act, and establishes this Privacy Policy as follows."}]},"sections":[{"id":"article-1","title":{"ko":"제1조 (개인정보의 처리 목적)","en":"Article 1 (Purposes of Processing Personal Information)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 다음 목적을 위해 필요한 범위에서 개인정보를 처리합니다."},{"type":"list","ordered":true,"items":[{"text":"**회원가입 및 계정 관리:** 회원가입, 만 19세 이상 가입 자격 확인, 로그인 및 회원 식별, 계정 보안, 회원 탈퇴 처리","number":1},{"text":"**언어교환 서비스 제공:** 회원의 언어 수준 확인, 언어교환 활동 운영, 커뮤니티 서비스 제공","number":2},{"text":"**게시판 운영:** 게시글·댓글 작성자 표시, 게시물 관리, 신고 접수 및 커뮤니티 운영 정책 집행","number":3},{"text":"**스터디 및 행사 운영:** 신청 접수, 참가자 확인, 일정 안내, 참가비 확인, 참가 관리 및 환불 처리","number":4},{"text":"**문의 및 고충 처리:** 문의 접수, 답변, 분쟁 해결 및 서비스 운영상 필요한 의사소통","number":5},{"text":"**서비스 보안:** 부정 이용 방지, 접근권한 관리 및 시스템 안정성 확보","number":6}]},{"type":"paragraph","text":"말모임은 위 목적 외로 개인정보를 이용해야 하는 경우 관련 법령에 따른 필요한 절차를 거칩니다."}],"en":[{"type":"paragraph","text":"MALMOIM processes personal information to the extent necessary for the following purposes."},{"type":"list","ordered":true,"items":[{"text":"**Registration and account management:** Registration, checking eligibility to register at age 19 or older, login and member identification, account security, and membership withdrawal","number":1},{"text":"**Providing language exchange services:** Understanding members’ language proficiency, operating language exchange activities, and providing community services","number":2},{"text":"**Operating the board:** Displaying authors of posts and comments, managing content, receiving reports, and enforcing community operating policies","number":3},{"text":"**Operating studies and events:** Receiving applications, identifying participants, providing schedule information, checking participation fees, managing participation, and processing refunds","number":4},{"text":"**Handling inquiries and complaints:** Receiving and responding to inquiries, resolving disputes, and communicating as necessary to operate the service","number":5},{"text":"**Service security:** Preventing misuse, managing access rights, and maintaining system stability","number":6}]},{"type":"paragraph","text":"If MALMOIM needs to use personal information for purposes other than those above, it follows the procedures required by applicable law."}]}},{"id":"article-2","title":{"ko":"제2조 (처리하는 개인정보의 항목 및 법적 근거)","en":"Article 2 (Personal Information Processed and Legal Bases)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"subheading","text":"① 회원가입"},{"type":"paragraph","text":"말모임은 회원가입 과정에서 다음 정보를 처리합니다."},{"type":"paragraph","text":"**필수 항목**"},{"type":"table","headers":["개인정보 항목","처리 목적"],"rows":[["이메일 주소","회원 식별, 로그인 및 계정 관리"],["비밀번호","회원 인증 및 계정 보호"],["닉네임","커뮤니티 내 회원 식별 및 작성자 표시"],["생년월일","만 19세 이상 가입 자격 확인"],["한국어 수준","한국어·영어 언어교환 서비스 제공"],["영어 수준","한국어·영어 언어교환 서비스 제공"]]},{"type":"paragraph","text":"**선택 항목**"},{"type":"table","headers":["개인정보 항목","처리 목적"],"rows":[["이름","별도 고지한 서비스상 목적"],["전화번호 및 국가번호","별도 고지한 연락·안내 목적"],["국적","별도 고지한 언어·문화교류 관련 목적"],["성별","별도 고지한 서비스상 목적"],["추가 외국어 및 언어 수준","추가 언어교환 정보 제공"]]},{"type":"paragraph","text":"선택 항목을 제공하지 않아도 기본적인 회원가입 및 커뮤니티 서비스 이용은 가능합니다."},{"type":"paragraph","text":"회원가입과 서비스 제공에 실제 필요한 개인정보는 「개인정보 보호법」 제15조 제1항 제4호 등 적용 가능한 법적 근거에 따라 처리합니다. 별도의 동의를 근거로 처리하는 항목은 수집 목적, 항목, 보유기간 및 동의 거부권을 안내하고 동의를 받습니다."},{"type":"paragraph","text":"회원가입 시 입력받는 생년월일은 가입 자격 확인에 사용하며, 회원 탈퇴 시까지 보유하는 것을 운영 원칙으로 합니다. 다만 전체 생년월일의 지속 보관 필요성은 개인정보 최소 수집 원칙에 따라 검토합니다."},{"type":"paragraph","text":"비밀번호는 인증 시스템을 통해 보호되며, 말모임은 비밀번호를 게시판이나 공개 프로필에 표시하지 않습니다."},{"type":"subheading","text":"② 게시판 및 커뮤니티 활동"},{"type":"list","ordered":false,"items":[{"text":"게시글·댓글: 작성자 닉네임, 작성 내용, 작성 및 수정 시각"},{"text":"신고 및 운영 조치: 신고 내용, 신고 대상, 처리 결과, 필요한 회원 식별정보"}]},{"type":"paragraph","text":"게시글 및 댓글의 작성자 닉네임은 다른 이용자에게 공개됩니다."},{"type":"subheading","text":"③ 스터디 및 행사 신청"},{"type":"paragraph","text":"행사에 따라 다음 정보를 필요한 범위에서 처리할 수 있습니다."},{"type":"list","ordered":false,"items":[{"text":"신청자 이름 또는 닉네임, 연락처 등 참가자 확인에 필요한 정보"},{"text":"신청 행사, 신청 내용 및 참가 여부"},{"text":"사전 계좌이체의 입금자명, 입금액, 입금일시 및 결제 상태"},{"text":"현장 결제의 납부 금액 및 납부 여부"},{"text":"환불에 필요한 은행명, 계좌번호, 예금주명, 환불 금액 및 처리 상태"}]},{"type":"paragraph","text":"구체적인 수집 항목과 필수·선택 여부는 각 행사 신청 단계에서 안내합니다."},{"type":"subheading","text":"④ 문의 및 서비스 이용"},{"type":"paragraph","text":"말모임은 문의 과정에서 이용자가 제공한 연락처와 문의 내용 등을 처리할 수 있습니다."},{"type":"paragraph","text":"또한 로그인 및 보안 기능을 위해 인증 쿠키, 접속정보, 서비스 이용 과정에서 생성되는 정보가 처리될 수 있습니다."}],"en":[{"type":"subheading","text":"① Registration"},{"type":"paragraph","text":"MALMOIM processes the following information during registration."},{"type":"paragraph","text":"**Required information**"},{"type":"table","headers":["Personal information","Purpose of processing"],"rows":[["Email address","Member identification, login, and account management"],["Password","Member authentication and account protection"],["Nickname","Member identification within the community and author attribution"],["Date of birth","Checking eligibility to register at age 19 or older"],["Korean proficiency","Providing Korean–English language exchange services"],["English proficiency","Providing Korean–English language exchange services"]]},{"type":"paragraph","text":"**Optional information**"},{"type":"table","headers":["Personal information","Purpose of processing"],"rows":[["Name","Service purposes notified separately"],["Phone number and country calling code","Contact and notification purposes notified separately"],["Nationality","Language and cultural exchange purposes notified separately"],["Gender","Service purposes notified separately"],["Additional languages and proficiency","Providing additional language exchange information"]]},{"type":"paragraph","text":"Basic registration and community services remain available without providing optional information."},{"type":"paragraph","text":"Personal information actually necessary for registration and service provision is processed on applicable legal bases, including Article 15(1)(4) of the Personal Information Protection Act. Where processing is based on separate consent, MALMOIM provides notice of the collection purpose, information collected, retention period, and right to refuse consent, and obtains consent."},{"type":"paragraph","text":"The date of birth entered during registration is used to check eligibility, and the operating principle is to retain it until membership withdrawal. However, the need to continue retaining the full date of birth is reviewed in accordance with the principle of data minimization."},{"type":"paragraph","text":"Passwords are protected through the authentication system, and MALMOIM does not display passwords on the board or in public profiles."},{"type":"subheading","text":"② Board and community activities"},{"type":"list","ordered":false,"items":[{"text":"Posts and comments: Author nickname, content, and creation and modification times"},{"text":"Reports and moderation actions: Report details, reported subject, processing outcome, and necessary member identifiers"}]},{"type":"paragraph","text":"The author nicknames of posts and comments are disclosed to other users."},{"type":"subheading","text":"③ Study and event applications"},{"type":"paragraph","text":"Depending on the event, the following information may be processed to the extent necessary."},{"type":"list","ordered":false,"items":[{"text":"Information necessary to identify participants, such as the applicant’s name or nickname and contact information"},{"text":"The event applied for, application details, and participation status"},{"text":"For advance bank transfers: Depositor name, deposit amount, deposit date and time, and payment status"},{"text":"For on-site payments: Amount paid and payment status"},{"text":"Bank name, account number, account holder name, refund amount, and processing status needed for refunds"}]},{"type":"paragraph","text":"The specific information collected and whether it is required or optional are explained at each event application stage."},{"type":"subheading","text":"④ Inquiries and service use"},{"type":"paragraph","text":"MALMOIM may process contact information and inquiry content provided by users when making inquiries."},{"type":"paragraph","text":"Authentication cookies, access information, and information generated through service use may also be processed for login and security functions."}]}},{"id":"article-3","title":{"ko":"제3조 (개인정보의 처리 및 보유기간)","en":"Article 3 (Processing and Retention Periods)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 다음 기준에 따라 개인정보를 보유하고 처리 목적 달성 후 파기합니다."},{"type":"table","headers":["구분","보유기간"],"rows":[["회원 계정 및 프로필 정보","회원 탈퇴 시까지"],["신고·제재 기록","처리 완료 후 3년"],["일반 문의 기록","처리 완료 후 6개월"],["행사 신청 및 참가자 정보","행사 종료 및 필요한 정산 완료 후 지체 없이 파기"],["환불을 위해 별도로 수집한 계좌정보","환불 완료 후 지체 없이 파기"],["게시글 및 댓글","회원 탈퇴 이후에도 유지할 수 있으며 작성자 식별정보는 분리 처리"],["법령상 보존이 필요한 거래·분쟁 기록","해당 법령에 따른 기간"]]},{"type":"paragraph","text":"관련 법령에 따라 개인정보를 보존해야 하는 경우에는 필요한 항목을 구분하여 해당 법정 기간 동안 보유하며, 다른 목적으로 사용하지 않습니다."}],"en":[{"type":"paragraph","text":"MALMOIM retains personal information according to the following criteria and destroys it after the purpose of processing has been achieved."},{"type":"table","headers":["Category","Retention period"],"rows":[["Member account and profile information","Until membership withdrawal"],["Reports and sanction records","Three years after processing is completed"],["General inquiry records","Six months after processing is completed"],["Event application and participant information","Destroyed without delay after the event ends and necessary settlement is completed"],["Account information collected separately for a refund","Destroyed without delay after the refund is completed"],["Posts and comments","May remain after membership withdrawal, with author-identifying information handled separately"],["Transaction and dispute records that must be retained by law","The period required by the applicable law"]]},{"type":"paragraph","text":"Where personal information must be preserved under applicable law, the necessary information is kept separately for the legally required period and is not used for other purposes."}]}},{"id":"article-4","title":{"ko":"제4조 (회원 탈퇴 및 게시물 처리)","en":"Article 4 (Membership Withdrawal and Content)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 회원은 말모임에서 제공하는 탈퇴 절차 또는 개인정보 문의처를 통해 회원 탈퇴를 요청할 수 있습니다."},{"type":"paragraph","text":"② 말모임은 회원 탈퇴 시 다른 법령에 따른 보존 의무 등 정당한 사유가 있는 경우를 제외하고 회원 계정 및 개인정보를 파기합니다."},{"type":"paragraph","text":"③ 회원이 작성한 게시글과 댓글은 커뮤니티의 대화 맥락과 다른 회원의 이용 편의를 위해 탈퇴 후에도 유지될 수 있습니다."},{"type":"paragraph","text":"④ 탈퇴 회원의 게시글·댓글 작성자 표시는 ''탈퇴한 회원(Former Member)''으로 변경하며, 공개 작성자 정보와 탈퇴 회원의 계정이 연결되지 않도록 처리합니다."},{"type":"paragraph","text":"⑤ 게시글이나 댓글 본문에 회원이 직접 입력한 개인정보는 작성자 이름 변경만으로 삭제되지 않을 수 있습니다. 회원은 탈퇴 전에 직접 게시물을 삭제하거나 개인정보 삭제를 요청할 수 있으며, 말모임은 관련 법령에 따라 처리합니다."}],"en":[{"type":"paragraph","text":"① Members may request withdrawal through the withdrawal procedure provided by MALMOIM or the privacy contact."},{"type":"paragraph","text":"② Upon withdrawal, MALMOIM destroys the member account and personal information unless there is a legitimate reason to retain them, such as a preservation obligation under another law."},{"type":"paragraph","text":"③ Posts and comments written by members may remain after withdrawal to preserve the context of community conversations and the convenience of other members."},{"type":"paragraph","text":"④ The author label on a withdrawn member’s posts and comments is changed to “탈퇴한 회원(Former Member),” and the public author information is handled so that it is not linked to the withdrawn member’s account."},{"type":"paragraph","text":"⑤ Personal information entered directly by a member in a post or comment may not be deleted merely by changing the author name. Members may delete their content themselves before withdrawal or request deletion of personal information, and MALMOIM handles such requests in accordance with applicable law."}]}},{"id":"article-5","title":{"ko":"제5조 (개인정보의 제3자 제공)","en":"Article 5 (Disclosure to Third Parties)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 이용자의 개인정보를 수집 목적 범위에서 처리하며, 관련 법령에 근거하거나 적법한 동의를 받는 등 허용되는 경우를 제외하고 제3자에게 제공하지 않습니다."},{"type":"paragraph","text":"행사 운영, 외부 협력 또는 다른 서비스 연동으로 제3자 제공이 필요한 경우에는 제공받는 자, 제공 목적, 개인정보 항목, 보유기간 및 적용되는 법적 근거를 확인하고 관련 법령에 따라 안내합니다."}],"en":[{"type":"paragraph","text":"MALMOIM processes personal information within the purposes for which it was collected and does not disclose it to third parties except where permitted, such as on a legal basis or with valid consent."},{"type":"paragraph","text":"If disclosure to a third party is necessary for event operations, external cooperation, or integration with another service, MALMOIM identifies the recipient, purpose, information, retention period, and applicable legal basis, and provides notice in accordance with applicable law."}]}},{"id":"article-6","title":{"ko":"제6조 (개인정보 처리업무의 위탁)","en":"Article 6 (Outsourcing of Personal Information Processing)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 웹사이트 운영을 위해 다음 서비스를 이용합니다."},{"type":"table","headers":["서비스","이용 목적 및 업무"],"rows":[["Supabase","회원 인증, 데이터베이스 및 회원·커뮤니티 정보 관리"],["Vercel","웹사이트 호스팅, 서버 처리 및 배포"]]},{"type":"paragraph","text":"각 서비스의 계약상 개인정보 처리 수탁자, 위탁업무 범위 및 재위탁 사항은 실제 계약과 서비스 설정을 기준으로 확인하여 공개합니다."},{"type":"paragraph","text":"행사 참가자 대상 문자 발송 등 별도의 외부 서비스를 실제로 사용하는 경우에는 해당 위탁 관계를 추가로 안내합니다."}],"en":[{"type":"paragraph","text":"MALMOIM uses the following services to operate its website."},{"type":"table","headers":["Service","Purpose and work performed"],"rows":[["Supabase","Member authentication, database, and management of member and community information"],["Vercel","Website hosting, server processing, and deployment"]]},{"type":"paragraph","text":"The contracted personal information processor for each service, the scope of outsourced work, and any further outsourcing will be verified and disclosed based on the actual contracts and service settings."},{"type":"paragraph","text":"If a separate external service is actually used, such as text messaging to event participants, the corresponding outsourcing relationship will also be disclosed."}]}},{"id":"article-7","title":{"ko":"제7조 (개인정보의 국외 이전)","en":"Article 7 (International Transfers of Personal Information)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 Supabase의 대한민국 서울 리전(ap-northeast-2)을 사용하여 주요 데이터베이스를 운영합니다."},{"type":"paragraph","text":"웹사이트 서버 기능은 Vercel을 통해 제공되며, 확인된 Functions 설정은 미국 워싱턴 D.C. 리전(iad1)입니다. 로그인, 게시판 및 행사 신청 등 개인정보가 포함된 요청이 해당 서버에서 처리될 수 있습니다."},{"type":"paragraph","text":"개인정보의 국외 이전이 발생하는 경우 말모임은 「개인정보 보호법」 제28조의8에 따른 적법한 근거를 확인하고 다음 사항을 구체적으로 안내합니다."},{"type":"list","ordered":true,"items":[{"text":"국외 이전의 법적 근거","number":1},{"text":"이전하는 개인정보 항목","number":2},{"text":"이전 국가, 시기 및 방법","number":3},{"text":"이전받는 자의 명칭과 연락처","number":4},{"text":"개인정보 이용 목적 및 보유기간","number":5},{"text":"국외 이전을 거부하는 방법, 절차 및 거부 시 효과","number":6}]}],"en":[{"type":"paragraph","text":"MALMOIM operates its primary database using Supabase’s Seoul, Republic of Korea region (ap-northeast-2)."},{"type":"paragraph","text":"Website server functions are provided through Vercel, and the confirmed Functions setting is the Washington, D.C., United States region (iad1). Requests containing personal information, including login, board, and event application requests, may be processed on those servers."},{"type":"paragraph","text":"Where an international transfer of personal information occurs, MALMOIM verifies a lawful basis under Article 28-8 of the Personal Information Protection Act and provides specific information about the following."},{"type":"list","ordered":true,"items":[{"text":"The legal basis for the international transfer","number":1},{"text":"The personal information transferred","number":2},{"text":"The destination country, timing, and method of transfer","number":3},{"text":"The recipient’s name and contact information","number":4},{"text":"The purposes of use and retention period","number":5},{"text":"How and through which procedures the transfer may be refused, and the effects of refusal","number":6}]}]}},{"id":"article-8","title":{"ko":"제8조 (개인정보의 파기 절차 및 방법)","en":"Article 8 (Destruction Procedures and Methods)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"① 말모임은 개인정보 보유기간이 만료되거나 처리 목적이 달성된 경우 관련 법령에 따라 지체 없이 파기합니다."},{"type":"paragraph","text":"② 전자적 파일은 복구가 어렵도록 안전한 방식으로 삭제하고, 종이 문서는 분쇄 또는 파쇄 등 적절한 방법으로 파기합니다."},{"type":"paragraph","text":"③ 다른 법령에 따라 보존해야 하는 정보는 필요한 범위에서 분리하여 보관하고 법정 기간이 종료되면 파기합니다."},{"type":"paragraph","text":"④ 백업, 시스템 로그 및 외부 서비스에 저장되는 개인정보는 실제 기술적·계약적 보관주기와 삭제 절차를 고려하여 관리합니다."}],"en":[{"type":"paragraph","text":"① When the retention period expires or the processing purpose has been achieved, MALMOIM destroys personal information without delay in accordance with applicable law."},{"type":"paragraph","text":"② Electronic files are securely deleted in a manner that makes recovery difficult, and paper documents are destroyed by appropriate means, such as shredding or pulverization."},{"type":"paragraph","text":"③ Information that must be preserved under another law is stored separately to the extent necessary and destroyed when the legally required period ends."},{"type":"paragraph","text":"④ Personal information stored in backups, system logs, and external services is managed with regard to actual technical and contractual retention cycles and deletion procedures."}]}},{"id":"article-9","title":{"ko":"제9조 (개인정보의 안전성 확보조치)","en":"Article 9 (Measures to Ensure Security)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 개인정보의 안전성을 확보하기 위해 관련 법령에 따른 기술적·관리적 보호조치를 실시합니다."},{"type":"paragraph","text":"보호조치의 범위는 접근권한 관리, 인증정보 보호, 전송구간 보호, 권한 없는 접근의 제한, 운영진의 개인정보 취급 관리 등 실제 서비스에 적용되는 조치를 기준으로 합니다."}],"en":[{"type":"paragraph","text":"MALMOIM implements technical and organizational protective measures required by applicable law to ensure the security of personal information."},{"type":"paragraph","text":"The scope of these measures is based on those actually applied to the service, including access-right management, protection of authentication information, protection during transmission, restrictions on unauthorized access, and management of organizers’ handling of personal information."}]}},{"id":"article-10","title":{"ko":"제10조 (쿠키 및 자동 수집 장치)","en":"Article 10 (Cookies and Automatic Collection Technologies)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 로그인 상태 유지와 회원 인증, 서비스 보안 등을 위해 쿠키 또는 유사한 기술을 사용할 수 있습니다."},{"type":"paragraph","text":"이용자는 웹 브라우저 설정을 통해 쿠키를 삭제하거나 차단할 수 있습니다. 다만 서비스 운영에 필요한 인증 쿠키를 차단하는 경우 로그인 등 일부 기능이 제한될 수 있습니다."},{"type":"paragraph","text":"말모임은 방문 분석 및 광고 추적 도구의 이용 여부를 실제 배포 상태에 따라 안내합니다."},{"type":"paragraph","text":"Meta Pixel 광고 추적 기능은 비활성화하기로 운영 정책을 결정했으며, 실제 운영 배포에서 중단 여부가 확인된 후 관련 고지를 갱신합니다."}],"en":[{"type":"paragraph","text":"MALMOIM may use cookies or similar technologies to maintain login status, authenticate members, and secure the service."},{"type":"paragraph","text":"Users may delete or block cookies through their browser settings. Blocking authentication cookies necessary for service operation may restrict certain functions, including login."},{"type":"paragraph","text":"MALMOIM discloses the use of visitor analytics and advertising tracking tools based on the actual deployment status."},{"type":"paragraph","text":"MALMOIM has decided, as an operating policy, to disable Meta Pixel advertising tracking and will update the relevant notice after confirming that tracking has stopped in the actual production deployment."}]}},{"id":"article-11","title":{"ko":"제11조 (커뮤니티 공개정보)","en":"Article 11 (Public Community Information)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"게시글·댓글에 표시되는 닉네임과 이용자가 직접 공개한 게시물은 다른 이용자가 열람할 수 있습니다."},{"type":"paragraph","text":"이메일 주소, 전화번호, 생년월일 등 비공개 회원정보는 게시글 작성자 정보로 공개하지 않습니다."},{"type":"paragraph","text":"이용자가 게시물 본문에 개인정보를 직접 공개할 경우 해당 정보가 다른 이용자에게 노출될 수 있으므로 공개 범위에 유의해야 합니다."}],"en":[{"type":"paragraph","text":"Other users may view the nicknames displayed on posts and comments and the content users disclose themselves."},{"type":"paragraph","text":"Private member information, such as email addresses, phone numbers, and dates of birth, is not disclosed as post author information."},{"type":"paragraph","text":"Users should consider the scope of disclosure when entering personal information in content, because that information may become visible to others."}]}},{"id":"article-12","title":{"ko":"제12조 (정보주체의 권리와 행사 방법)","en":"Article 12 (Individuals’ Rights and How to Exercise Them)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"이용자는 관련 법령에서 정한 바에 따라 자신의 개인정보에 대한 열람, 정정, 삭제, 처리정지 및 동의 철회 등의 권리를 행사할 수 있습니다."},{"type":"paragraph","text":"개인정보 관련 요청은 다음 이메일로 접수할 수 있습니다."},{"type":"paragraph","text":"**cometomalmoim@gmail.com**"},{"type":"paragraph","text":"말모임은 요청자의 본인 여부와 법령상 처리 제한 사유를 확인하고 관련 법령에 따라 처리합니다."}],"en":[{"type":"paragraph","text":"Users may exercise rights under applicable law concerning their personal information, including access, correction, deletion, suspension of processing, and withdrawal of consent."},{"type":"paragraph","text":"Requests concerning personal information may be submitted to the following email address."},{"type":"paragraph","text":"**cometomalmoim@gmail.com**"},{"type":"paragraph","text":"MALMOIM verifies the requester’s identity and any statutory grounds restricting processing of the request and handles the request in accordance with applicable law."}]}},{"id":"article-13","title":{"ko":"제13조 (회원가입 연령 제한)","en":"Article 13 (Minimum Registration Age)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 만 19세 이상을 회원가입 대상으로 합니다."},{"type":"paragraph","text":"가입자는 정확한 생년월일을 입력해야 하며, 가입 자격을 충족하지 않는 경우 회원가입이 제한됩니다."},{"type":"paragraph","text":"생년월일 입력을 통한 연령 확인은 공인된 신원확인 또는 본인인증과 구분됩니다."}],"en":[{"type":"paragraph","text":"Registration with MALMOIM is for people aged 19 or older."},{"type":"paragraph","text":"Applicants must enter an accurate date of birth, and registration is restricted if they do not meet the eligibility requirements."},{"type":"paragraph","text":"An age check based on an entered date of birth is distinct from officially recognized identity verification or personal authentication."}]}},{"id":"article-14","title":{"ko":"제14조 (개인정보 보호 담당 부서)","en":"Article 14 (Department Responsible for Personal Information Protection)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"list","ordered":false,"items":[{"text":"개인정보처리자: 말모임(MALMOIM)"},{"text":"운영 형태: 비법인 비영리 언어교환 커뮤니티"},{"text":"개인정보 보호 담당 부서: 말모임 운영팀"},{"text":"개인정보 관련 문의: cometomalmoim@gmail.com"},{"text":"홈페이지: https://malmoim.com"}]},{"type":"paragraph","text":"이용자는 개인정보 관련 불만, 권리행사 및 기타 문의를 위 연락처로 접수할 수 있습니다."}],"en":[{"type":"list","ordered":false,"items":[{"text":"Personal information controller: MALMOIM"},{"text":"Form of operation: Unincorporated nonprofit language exchange community"},{"text":"Department responsible for personal information protection: MALMOIM Operations Team"},{"text":"Privacy inquiries: cometomalmoim@gmail.com"},{"text":"Website: https://malmoim.com"}]},{"type":"paragraph","text":"Users may submit privacy complaints, rights requests, and other inquiries through the contact details above."}]}},{"id":"article-15","title":{"ko":"제15조 (개인정보 침해 구제)","en":"Article 15 (Remedies for Personal Information Infringement)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"개인정보 침해에 관한 상담이나 구제가 필요한 경우 개인정보침해신고센터, 개인정보분쟁조정위원회 등 관계 기관의 도움을 받을 수 있습니다."},{"type":"list","ordered":false,"items":[{"text":"개인정보침해신고센터: 국번 없이 118"},{"text":"개인정보분쟁조정위원회: 1833-6972"}]}],"en":[{"type":"paragraph","text":"Users who need advice or remedies concerning infringement of personal information may seek help from relevant bodies, including the Personal Information Infringement Report Center and the Personal Information Dispute Mediation Committee."},{"type":"list","ordered":false,"items":[{"text":"Personal Information Infringement Report Center: 118 (without an area code)"},{"text":"Personal Information Dispute Mediation Committee: 1833-6972"}]}]}},{"id":"article-16","title":{"ko":"제16조 (개인정보 처리방침의 변경)","en":"Article 16 (Changes to the Privacy Policy)"},"paragraphs":{"ko":[],"en":[]},"blocks":{"ko":[{"type":"paragraph","text":"말모임은 관련 법령 또는 서비스 운영 내용이 변경되는 경우 개인정보 처리방침을 개정할 수 있습니다."},{"type":"paragraph","text":"개정된 방침은 홈페이지를 통해 공개하며, 필요한 경우 변경 내용과 시행일을 별도로 안내합니다."}],"en":[{"type":"paragraph","text":"MALMOIM may revise this Privacy Policy when applicable laws or service operations change."},{"type":"paragraph","text":"The revised policy will be published on the website, and changes and the effective date will be announced separately where necessary."}]}}]}'::jsonb,
'{"version":"signup-v1","basis":"contract","purpose":{"ko":"회원가입 및 계정 관리, 만 19세 이상 가입 자격 확인, 커뮤니티 내 회원 식별 및 작성자 표시, 한국어·영어 언어교환 서비스 제공","en":"Registration and account management, eligibility checks for ages 19 and over, member identification and author display in the community, and Korean–English language exchange services"},"items":{"ko":"이메일 주소, 비밀번호, 닉네임, 생년월일, 한국어 수준, 영어 수준","en":"Email address, password, nickname, date of birth, Korean proficiency, and English proficiency"},"retention":{"ko":"회원 탈퇴 시까지. 법령상 보존 의무가 있는 정보는 개인정보 처리방침 제3조에 따라 별도 보관합니다.","en":"Until membership withdrawal. Information subject to statutory retention is stored separately as described in Article 3 of the Privacy Policy."},"refusal":{"ko":"필수 항목을 제공하지 않으면 회원가입을 진행할 수 없습니다. 현재 가입 화면에서는 선택 개인정보를 수집하지 않습니다.","en":"Registration cannot proceed without the required information. Optional personal information is not collected on the current signup form."}}'::jsonb,true);
create or replace function public.member_registration_ready() returns text
language sql stable security definer set search_path='' as $$
 select collection_version from public.member_registration_policies where enabled
$$;
revoke all on function public.member_registration_ready() from public,anon,authenticated;

-- MANUAL candidate: apply only with explicit approval and reviewed prerequisites.
-- Auth users without this app's one-use reference are unaffected.

create table public.member_signup_requests(
 token uuid primary key default gen_random_uuid(),
 email text not null check(email=lower(btrim(email)) and length(email) between 3 and 254),
 nickname text not null,profile jsonb not null,languages jsonb not null,
 collection_version text not null references public.member_registration_policies(collection_version),
 terms_version text not null,privacy_version text not null,
 terms_accepted boolean not null check(terms_accepted),collection_accepted boolean not null,
 created_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null default (clock_timestamp()+interval '1 hour')
);
create index member_signup_request_expiry on public.member_signup_requests(expires_at);
create index member_signup_request_email on public.member_signup_requests(email,created_at);
alter table public.member_signup_requests enable row level security;
alter table public.member_signup_requests force row level security;
revoke all on public.member_signup_requests from public,anon,authenticated;

create function public.prepare_member_registration(p_email text,p_nickname text,p_profile jsonb,p_languages jsonb,p_consent_version text,p_terms_version text,p_privacy_version text,p_terms_accepted boolean,p_collection_accepted boolean)
returns uuid language plpgsql security definer set search_path='' as $$
declare selected_email text:=lower(btrim(p_email));policy public.member_registration_policies;birth date;result uuid;
begin
 if selected_email is null or length(selected_email)>254 or selected_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then raise exception 'Invalid registration request' using errcode='23514';end if;
 select * into policy from public.member_registration_policies where enabled and collection_version=p_consent_version for share;
 if not found or public.member_registration_v2_ready() is null or p_terms_version is distinct from policy.terms_version or p_privacy_version is distinct from policy.privacy_version or p_terms_accepted is distinct from true or (policy.collection_basis='consent' and p_collection_accepted is distinct from true) then raise exception 'Policy acceptance required' using errcode='42501';end if;
 if not public.member_nickname_valid(btrim(normalize(p_nickname,NFKC))) or jsonb_typeof(p_profile) is distinct from 'object' or jsonb_typeof(p_languages) is distinct from 'array' or jsonb_array_length(p_languages)>3 then raise exception 'Invalid registration request' using errcode='23514';end if;
 if length(p_profile::text)>4000 or length(p_languages::text)>2000 or exists(select 1 from jsonb_object_keys(p_profile) k where k not in ('name','phone_country_code','phone_number','nationality_code','gender','birth_date','korean_proficiency','english_proficiency')) then raise exception 'Unexpected profile field' using errcode='22023';end if;
 if coalesce(p_profile->>'birth_date','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Birth date required' using errcode='23514';end if;
 begin birth:=(p_profile->>'birth_date')::date;exception when others then raise exception 'Invalid birth date' using errcode='23514';end;
 if birth<date '0001-01-01' or birth>((now() at time zone 'Asia/Seoul')::date-interval '19 years')::date or
    coalesce(p_profile->>'korean_proficiency','') not in ('none','basic','conversational','fluent','native') or
    coalesce(p_profile->>'english_proficiency','') not in ('none','basic','conversational','fluent','native') then raise exception 'Invalid eligibility or proficiency' using errcode='23514';end if;
 perform pg_advisory_xact_lock(hashtextextended(selected_email,20261023));
 -- Expired temporary requests only; no Auth/profile/community/event data is deleted.
 delete from public.member_signup_requests where expires_at<clock_timestamp();
 if (select count(*) from public.member_signup_requests where email=selected_email and created_at>clock_timestamp()-interval '1 minute')>=5 then raise exception 'Rate limited' using errcode='P0003';end if;
 insert into public.member_signup_requests(email,nickname,profile,languages,collection_version,terms_version,privacy_version,terms_accepted,collection_accepted)
 values(selected_email,p_nickname,p_profile,p_languages,p_consent_version,p_terms_version,p_privacy_version,true,coalesce(p_collection_accepted,false)) returning token into result;
 return result;
end $$;
revoke all on function public.prepare_member_registration(text,text,jsonb,jsonb,text,text,text,boolean,boolean) from public,anon,authenticated;
grant execute on function public.prepare_member_registration(text,text,jsonb,jsonb,text,text,text,boolean,boolean) to anon,authenticated;

create function public.member_signup_auth_profile() returns trigger language plpgsql security definer set search_path='' as $$
declare request public.member_signup_requests;reference text:=new.raw_user_meta_data->>'malmoim_registration_token';prior_sub text:=current_setting('request.jwt.claim.sub',true);result uuid;
begin
 if reference is null then return new;end if;
 if reference !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then raise exception 'Invalid registration request' using errcode='23514';end if;
 select * into request from public.member_signup_requests where token=reference::uuid and expires_at>clock_timestamp() and email=lower(btrim(new.email)) for update;
 if not found then raise exception 'Invalid registration request' using errcode='23514';end if;
 -- Scope impersonation strictly to the trusted just-inserted Auth UUID, restore
 -- the previous claim before returning. The trigger is not callable as an RPC.
 perform set_config('request.jwt.claim.sub',new.id::text,true);
 result:=public.save_member_registration_v2(request.nickname,request.profile,request.languages,request.collection_version,request.terms_version,request.privacy_version,request.terms_accepted,request.collection_accepted);
 perform set_config('request.jwt.claim.sub',coalesce(prior_sub,''),true);
 if result is distinct from new.id then raise exception 'Registration did not complete';end if;
 delete from public.member_signup_requests where token=request.token;
 return new;
end $$;
revoke all on function public.member_signup_auth_profile() from public,anon,authenticated;
create trigger member_signup_auth_profile after insert on auth.users for each row execute function public.member_signup_auth_profile();
notify pgrst,'reload schema';

commit;
